package com.example.auth;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.Instant;
import java.time.temporal.ChronoUnit;
import java.util.concurrent.atomic.AtomicReference;

@Service
public class TokenService {

    private final TokenRepository tokenRepository;
    private final UserRepository userRepository;

    @Autowired
    public TokenService(TokenRepository tokenRepository, UserRepository userRepository) {
        this.tokenRepository = tokenRepository;
        this.userRepository = userRepository;
    }

    public Token createToken(String tokenValue, Long userId, String tokenType, long lifetimeMinutes) {
        long now = System.currentTimeMillis();
        long expiresAt = now + lifetimeMinutes * 60 * 1000;
        return new Token(tokenValue, userId, tokenType, now, expiresAt, false, false);
    }

    @Transactional
    public void saveToken(Token token) {
        tokenRepository.save(token);
    }

    public boolean isTokenValid(String tokenValue, String tokenType) {
        Token token = tokenRepository.findByTokenValueAndIsRevokedFalseAndIsConsumedFalse(tokenValue)
                .orElse(null);
        if (token == null) return false;
        if (token.getTokenType().equals(tokenType)) {
            long now = System.currentTimeMillis();
            return !token.isRevoked() && !token.isConsumed() && now < token.getExpiresAt();
        }
        return false;
    }

    public boolean isValidOneTimeToken(String tokenValue) {
        Token token = tokenRepository.findByTokenValueAndIsRevokedFalseAndIsConsumedFalse(tokenValue)
                .orElse(null);
        if (token == null) return false;
        if (token.getTokenType().equals("ONE_TIME")) {
            long now = System.currentTimeMillis();
            return !token.isRevoked() && !token.isConsumed() && now < token.getExpiresAt();
        }
        return false;
    }

    @Transactional
    public void consumeOneTimeToken(String tokenValue) {
        Token token = tokenRepository.findByTokenValueAndIsRevokedFalseAndIsConsumedFalse(tokenValue);
        if (token != null) {
            token.setIsConsumed(true);
            token.setIsRevoked(true);
            tokenRepository.save(token);
        }
    }

    @Transactional
    public void revokeToken(String tokenValue) {
        Token token = tokenRepository.findByTokenValueAndIsRevokedFalse(tokenValue);
        if (token != null) {
            token.setIsRevoked(true);
            tokenRepository.save(token);
        }
    }

    @Transactional
    public void revokeAllTokensForUser(Long userId) {
        List<Token> tokens = tokenRepository.findAllByUserId(userId);
        for (Token token : tokens) {
            token.setIsRevoked(true);
            tokenRepository.save(token);
        }
    }

    public long getIssuedAt(String tokenValue) {
        Token token = tokenRepository.findByTokenValueAndIsRevokedFalse(tokenValue);
        return token != null ? token.getIssuedAt() : 0;
    }

    public boolean isTokenRevoked(String tokenValue) {
        Token token = tokenRepository.findByTokenValueAndIsRevokedFalse(tokenValue);
        return token != null && token.isRevoked();
    }

    public boolean isTokenConsumed(String tokenValue) {
        Token token = tokenRepository.findByTokenValueAndIsRevokedFalse(tokenValue);
        return token != null && token.isConsumed();
    }

    public List<Token> getTokensByUserId(Long userId) {
        return tokenRepository.findAllByUserId(userId);
    }

    public Token getValidToken(String tokenValue, String tokenType) {
        Token token = tokenRepository.findByTokenValueAndIsRevokedFalseAndIsConsumedFalse(tokenValue);
        if (token != null && token.getTokenType().equals(tokenType)) {
            long now = System.currentTimeMillis();
            if (now < token.getExpiresAt()) {
                return token;
            }
        }
        return null;
    }

    public void cleanupTokens() {
        long now = System.currentTimeMillis();
        long cleanupLimit = now - 24 * 60 * 60 * 1000; // 24 hours ago

        int count = tokenRepository.deleteByExpiresAtLessThan(cleanupLimit);
        System.out.println("[CLEANUP] Deleted " + count + " tokens");
    }

    public long getNow() {
        return System.currentTimeMillis();
    }
}
