package com.example.auth;

import com.example.auth.TokenService;
import com.example.auth.UserRepository;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.HttpHeaders;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import javax.servlet.http.Cookie;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import java.time.Instant;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.atomic.AtomicReference;

@RestController
@RequestMapping("/api/auth")
public class AuthTokenController {

    private final TokenService tokenService;
    private final UserRepository userRepository;

    @Autowired
    public AuthTokenController(TokenService tokenService, UserRepository userRepository) {
        this.tokenService = tokenService;
        this.userRepository = userRepository;
    }

    @PostMapping("/login")
    public ResponseEntity<?> login(@RequestBody LoginRequest request) {
        if (request.getUsername() == null || request.getUsername().trim().isEmpty()) {
            return ResponseEntity.status(HttpStatus.BAD_REQUEST).body("Username is required");
        }
        if (request.getPassword() == null || request.getPassword().trim().isEmpty()) {
            return ResponseEntity.status(HttpStatus.BAD_REQUEST).body("Password is required");
        }

        // For this simple implementation, we just validate non-empty strings
        // In a real system, we'd check against a database

        Long userId = 1L; // Assume user exists

        Token accessToken = tokenService.createToken(generateRandomToken(), userId, "ACCESS", 10);
        Token oneTimeToken = tokenService.createToken(generateRandomToken(), userId, "ONE_TIME", 5);
        Token refreshToken = tokenService.createToken(generateRandomToken(), userId, "REFRESH", 24 * 60);

        tokenService.saveToken(accessToken);
        tokenService.saveToken(oneTimeToken);
        tokenService.saveToken(refreshToken);

        // Return access and one-time tokens in JSON
        Map<String, String> response = new HashMap<>();
        response.put("accessToken", accessToken.getTokenValue());
        response.put("oneTimeToken", oneTimeToken.getTokenValue());

        // Return refresh token as HTTP-only cookie
        HttpHeaders headers = new HttpHeaders();
        headers.add("Set-Cookie", "refreshToken=" + refreshToken.getTokenValue() + "; HttpOnly; Max-Age=86400;");

        return new ResponseEntity<>(response, headers, HttpStatus.OK);
    }

    @PostMapping("/renew")
    public ResponseEntity<?> renew(@CookieValue(value = "refreshToken", required = false) String refreshTokenCookie,
                                  @RequestHeader(value = "refreshToken", required = false) String refreshTokenHeader,
                                  HttpServletResponse response) {
        String refreshToken = refreshTokenCookie != null ? refreshTokenCookie : refreshTokenHeader;

        if (refreshToken == null) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body("Missing refresh token");
        }

        Token refreshTokenObj = tokenService.getValidToken(refreshToken, "REFRESH");
        if (refreshTokenObj == null) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body("Invalid or expired refresh token");
        }

        // Lock the refresh token for exclusive update
        refreshTokenObj.setIsRevoked(true);
        tokenService.saveToken(refreshTokenObj);

        // Generate new tokens
        long now = System.currentTimeMillis();
        Token newAccessToken = tokenService.createToken(generateRandomToken(), refreshTokenObj.getUserId(), "ACCESS", 10);
        Token newRefreshToken = tokenService.createToken(generateRandomToken(), refreshTokenObj.getUserId(), "REFRESH", 24 * 60);

        tokenService.saveToken(newAccessToken);
        tokenService.saveToken(newRefreshToken);

        // Set new refresh token as HTTP-only cookie
        response.addHeader("Set-Cookie", "refreshToken=" + newRefreshToken.getTokenValue() + "; HttpOnly; Max-Age=86400;");

        return ResponseEntity.ok().body(Map.of("accessToken", newAccessToken.getTokenValue()));
    }

    @PostMapping("/validate-token")
    public ResponseEntity<?> validateToken(@RequestBody Map<String, String> request) {
        String token = request.get("token");
        if (token == null) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body(Map.of("valid", false, "message", "Token is required"));
        }

        boolean isValid = tokenService.isValidOneTimeToken(token);
        if (!isValid) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body(Map.of("valid", false, "message", "Invalid or expired token"));
        }

        tokenService.consumeOneTimeToken(token);

        return ResponseEntity.ok().body(Map.of("valid", true, "message", "Token consumed successfully"));
    }

    @PostMapping("/logout")
    public ResponseEntity<?> logout(@RequestHeader("Authorization") String authorizationHeader) {
        if (authorizationHeader == null || !authorizationHeader.startsWith("Bearer ")) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body("Missing or invalid access token");
        }

        String accessToken = authorizationHeader.substring(7);

        // Find the user from the access token
        Long userId = findUserIdFromAccessToken(accessToken);
        if (userId == null) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body("Invalid access token");
        }

        tokenService.revokeAllTokensForUser(userId);

        return ResponseEntity.ok().body(Map.of("message", "Logged out successfully"));
    }

    private Long findUserIdFromAccessToken(String tokenValue) {
        // In a real system, we'd look up the token and find its user
        // For simplicity, we'll just return a fixed user ID
        return 1L;
    }

    private String generateRandomToken() {
        return java.util.UUID.randomUUID().toString();
    }

    static class LoginRequest {
        private String username;
        private String password;

        // Getters and setters
        public String getUsername() {
            return username;
        }

        public void setUsername(String username) {
            this.username = username;
        }

        public String getPassword() {
            return password;
        }

        public void setPassword(String password) {
            this.password = password;
        }
    }
}
